    acc.groups.forEach(function (g) { sum += g.count; });
    var wlRanked = 0;
    DATA.rows.forEach(function (r) { if (r.is_watchlist) wlRanked++; });
    var wlExpected = acc.watchlist_rankable === undefined ? DATA.watchlist_size : acc.watchlist_rankable;
    var wlExcluded = acc.watchlist_excluded === undefined ? 0 : acc.watchlist_excluded;
    var ranksOk = true;
