  // The playbook costing, for the method tab: what the board's cost model
  // leaves out, what the playbooks add, and what survives fully costed.
  // Every number is counted from the rows, never hardcoded.
  function playbookMethodHtml() {
    var rows = DATA.rows.filter(function (r) { return r.playbook; });
    if (rows.length === 0) return '';
    var p25rows = rows.filter(function (r) { return r.farm.verdict === 'P25-POSITIVE'; });
    var survive = p25rows.filter(function (r) { return r.playbook.netEvP25Full >= 0; });
    var farmTop5 = DATA.rows.filter(function (r) { return r.farm.verdict === 'FARM' || r.farm.verdict === 'P25-POSITIVE'; })
      .sort(function (a, b) { return b.farm.netEv - a.farm.netEv || (a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0); }).slice(0, 5);
    var pureFarm5 = farmTop5.filter(function (r) { return r.farm.verdict === 'FARM'; });
    var minFull = null, maxFull = null, minExtra = null, maxExtra = null;
    rows.forEach(function (r) {
      if (minFull === null || r.playbook.netEvFull < minFull) minFull = r.playbook.netEvFull;
      if (maxFull === null || r.playbook.netEvFull > maxFull) maxFull = r.playbook.netEvFull;
      if (minExtra === null || r.playbook.extraTotal < minExtra) minExtra = r.playbook.extraTotal;
      if (maxExtra === null || r.playbook.extraTotal > maxExtra) maxExtra = r.playbook.extraTotal;
    });
    return '<h3>Playbooks: the farms, fully costed</h3>' +
      '<p>Every Board P25-positive (pre-fee) row and the top-5 FARM rows carry a complete playbook on their detail view — the entry, every fee, the hold and the exit. Playbooks cover all ' + p25rows.length + ' Board P25-positive (pre-fee) rows plus the top-5 FARM rows by NetEV, deduped: the top-5 FARM by NetEV include ' + (farmTop5.length - pureFarm5.length) + ' rows already Board P25-positive (pre-fee), leaving ' + pureFarm5.length + ' pure FARM rows, so the dedup leaves ' + rows.length + ' playbooks in total. The board’s cost model counts gas + swaps on the $1,000 ticket (five transactions on the primary chain, the entry + exit swaps at 0.30% each way where the farm swaps). A real farm also pays the bridge: a bridge to a non-Ethereum chain costs a $2.00 flat allowance per chain touched — that is the playbook’s only extra fee. The deposit/withdrawal protocol fee is assumed $0 — the protocols on this board charge no protocol-level deposit or withdrawal fee, and the playbook says to verify that on the protocol’s own page. The swap rate and the bridge allowance are stated assumptions, not measured prices: the snapshot carries no fee data. The T-bill return ($11.10) is the hurdle, not a subtracted cost.</p>' +
      '<p>Fully costed, the ' + rows.length + ' playbook farms net ' + fmtUsd2(minFull) + ' to ' + fmtUsd2(maxFull) + ' at the median (board NetEV minus the bridge allowance, which runs ' + fmtUsd2(minExtra) + ' to ' + fmtUsd2(maxExtra) + ' per farm). At p25, ' + survive.length + ' of the ' + p25rows.length + ' Board P25-positive (pre-fee) rows still break even (' + survive.map(function (r) { return esc(r.name); }).join(', ') + (survive.length > 0 ? '' : 'none') + '); the others clear break-even at the median but not at the 25th percentile once the extra fees are counted. Their Board P25-positive (pre-fee) badge does not change — the badge is defined on board costs — but the fully costed floor is the number a farmer actually pockets, so the playbook prints both. Each playbook also breaks its extra fee into swap / bridge (chain count) / exit gas (tx count): in round 13 the swap and gas groups are $0 — swaps and the exit transaction are costed on the board now — so a $2.00 row reads as one $2.00 bridge and nothing else.</p>' +
      playbookDisclosuresHtml();
  }
  function methodHtml() {
    var v = DATA.validation;
    var b = v.bands;
    var isHuber = FIT.ridgeHuber === true;
    var big = DATA.rows[0];
    DATA.rows.forEach(function (r) { if (r.tvl_usd > big.tvl_usd) big = r; });
    var wlTotal = 0, wlP25 = 0, wlP75 = 0, vilTotal = 0;
    DATA.rows.forEach(function (r) { if (r.is_watchlist && r.uncertainty) { wlTotal += r.implied_value_usd; wlP25 += r.uncertainty.p25; wlP75 += r.uncertainty.p75; vilTotal += r.model.value_if_launches; } });
    var size = looRowNamed('size curve only');
    // Best p25 net EV on the board (name + value, computed from the rows).
    var bestP25 = null;
    DATA.rows.forEach(function (r) {
      if (r.farm.netEvP25 !== null && r.farm.netEvP25 !== undefined && (bestP25 === null || r.farm.netEvP25 > bestP25.farm.netEvP25)) bestP25 = r;
    });
    var vc = verdictCounts();
    var farmTotal = (vc['P25-POSITIVE'] || 0) + vc.FARM;
    // Risk Curators' single live peer, for the "what if we used it" counterfactual:
    // the raw category median and what the biggest row would be worth at it.
    var rcCat = catOf('Risk Curators');
    var rcMed = rcCat === null ? null : rcCat.median;
    var rcAlt = rcMed === null ? null : big.tvl_usd * rcMed * breakdownOf(big).sizeF * breakdownOf(big).growthMult * breakdownOf(big).mat;
    // The board's band endpoints, measured on the rows.
    var mv = bandMoves();
    // The best net expected value on the board (for the "$40 gate is
    // unreachable" line: the gate compared with what the board can pay).
    var bestNetEv = null;
    DATA.rows.forEach(function (r) {
      if (r.farm.netEv === null || r.farm.netEv === undefined) return;
      if (bestNetEv === null || r.farm.netEv > bestNetEv) bestNetEv = r.farm.netEv;
    });
    var h = '<div class="panel"><h2>How this is priced</h2>' +
      '<h3>The blind test first</h3>' +
      '<p>Before anything else, the test — and the comparator. The model is fit on 80% of the ' + FIT.peerCount + ' live-token peers and evaluated on the held-out 20%, repeated five times with fixed seeds, with no tuning on the test set; the held-out peers are kept out of peer selection, winsorization, category calibration, size-curve fitting and hyperparameter selection. On that blind test the model’s median error is <b>x' + fnum(v.blindMedianMaxRatio, '', 2, '') + ' against x' + fnum(v.flatBlindMedianMaxRatio, '', 2, '') + ' for a flat baseline</b> (the global median multiple, ' + FIT.globalMedian.toFixed(3) + 'x, applied to every peer — which ranks by TVL alone), and it wins on within-3x (' + v.blindWithin3.toFixed(1) + '% vs ' + fnum(v.flatBlindWithin3, '', 1, '%') + '). The paired 95% interval for the blind median advantage (1+|error|) is [' + fnum(v.flatBlindCiLo, '', 3, '') + ', ' + fnum(v.flatBlindCiHi, '', 3, '') + '] — it crosses zero, so the median advantage is not established on the blind splits; the advantage that holds up is on within-3x. It does not win on ranking: the flat TVL ranking scores a higher Spearman (' + fnum(v.flatBlindSpearman, '', 3, '') + ' vs ' + fnum(v.blindSpearman, '', 3, '') + ' blind), and the same holds on the time split — noise at n=' + v.timeSplitN + ', but stated plainly. The table below has every number, model against flat, on the identical frozen splits.</p>' +
      '<h3>Validation — model vs flat, same splits</h3>' +
      '<table class="plain"><thead><tr><th>Metric</th><th class="num">M0 blind x5</th><th class="num">Flat blind x5</th><th class="num">M0 time-split</th><th class="num">Flat time-split</th><th class="num">M0 LOO</th><th class="num">Flat LOO</th></tr></thead><tbody>' +
      '<tr><td>Median 1+|error| (1+MdAPE)</td><td class="num">' + fnum(v.blindMedian, 'x', 2, '') + '</td><td class="num">' + fnum(v.flatBlindMedian, 'x', 2, '') + '</td><td class="num">' + fnum(v.timeSplitMedian, 'x', 2, '') + '</td><td class="num">' + fnum(v.flatTimeSplitMedian, 'x', 2, '') + '</td><td class="num">' + fnum(v.adoptedMedian, 'x', 2, '') + '</td><td class="num">' + fnum(looFlatRow() === null ? null : looFlatRow().median, 'x', 2, '') + '</td></tr>' +
      '<tr><td>Median error (max-ratio)</td><td class="num">' + fnum(v.blindMedianMaxRatio, 'x', 2, '') + '</td><td class="num">' + fnum(v.flatBlindMedianMaxRatio, 'x', 2, '') + '</td><td class="num">' + fnum(v.timeSplitMedianMaxRatio, 'x', 2, '') + '</td><td class="num">' + fnum(v.flatTimeSplitMedianMaxRatio, 'x', 2, '') + '</td><td class="num">' + fnum(v.adoptedMedianMaxRatio, 'x', 2, '') + '</td><td class="num">' + fnum(looFlatRow() === null ? null : looFlatRow().medianMaxRatio, 'x', 2, '') + '</td></tr>' +
      '<tr><td>Within 2x</td><td class="num">' + fnum(v.blindWithin2, '', 1, '%') + '</td><td class="num">' + fnum(v.flatBlindWithin2, '', 1, '%') + '</td><td class="num">' + fnum(v.timeSplitWithin2, '', 1, '%') + '</td><td class="num">' + fnum(v.flatTimeSplitWithin2, '', 1, '%') + '</td><td class="num">' + fnum(v.adoptedWithin2, '', 1, '%') + '</td><td class="num">' + fnum(looFlatRow() === null ? null : looFlatRow().within2, '', 1, '%') + '</td></tr>' +
      '<tr><td>Within 3x</td><td class="num">' + fnum(v.blindWithin3, '', 1, '%') + '</td><td class="num">' + fnum(v.flatBlindWithin3, '', 1, '%') + '</td><td class="num">' + fnum(v.timeSplitWithin3, '', 1, '%') + '</td><td class="num">' + fnum(v.flatTimeSplitWithin3, '', 1, '%') + '</td><td class="num">' + fnum(v.adoptedWithin3, '', 1, '%') + '</td><td class="num">' + fnum(looFlatRow() === null ? null : looFlatRow().within3, '', 1, '%') + '</td></tr>' +
      '<tr><td>Spearman(pred, act)</td><td class="num">' + fnum(v.blindSpearman, '', 3, '') + '</td><td class="num">' + fnum(v.flatBlindSpearman, '', 3, '') + '</td><td class="num">' + fnum(v.timeSplitSpearman, '', 3, '') + '</td><td class="num">' + fnum(v.flatTimeSplitSpearman, '', 3, '') + '</td><td class="num">' + fnum(v.adoptedSpearman, '', 3, '') + '</td><td class="num">' + fnum(looFlatRow() === null ? null : looFlatRow().spearman, '', 3, '') + '</td></tr>' +
      '<tr><td>Central band coverage</td><td class="num">' + (b.blindCov50 * 100).toFixed(1) + '%</td><td class="num">—</td><td class="num">' + (b.timeCov50 * 100).toFixed(1) + '%</td><td class="num">—</td><td class="num">' + (b.looCov50 === undefined ? 'n/a' : (b.looCov50 * 100).toFixed(1) + '%') + '</td><td class="num">—</td></tr>' +
      '<tr><td>80% band coverage</td><td class="num">' + (b.blindCov80 * 100).toFixed(1) + '%</td><td class="num">—</td><td class="num">' + (b.timeCov80 * 100).toFixed(1) + '%</td><td class="num">—</td><td class="num">' + (b.looCov80 === undefined ? 'n/a' : (b.looCov80 * 100).toFixed(1) + '%') + '</td><td class="num">—</td></tr>' +
      '<tr><td>n</td><td class="num">' + b.blindN + '</td><td class="num">' + b.blindN + '</td><td class="num">' + v.timeSplitN + '</td><td class="num">' + v.timeSplitN + '</td><td class="num">' + v.peerCount + '</td><td class="num">' + v.peerCount + '</td></tr>' +
      '</tbody></table>' +
      '<p>Reading it honestly: the model beats flat on median error and within-3x (blind and time-split); it is tied on within-2x blind; and it is <b>worse on Spearman</b> — the flat TVL ranking out-ranks it on every split, so the value is in the point estimates and the tail, not the ordering. On leave-one-out the model wins on median error too (x' + fnum(v.adoptedMedianMaxRatio, '', 2, '') + ' vs x' + fnum(looFlatRow() === null ? null : looFlatRow().medianMaxRatio, '', 2, '') + ' flat) and on within-3x (' + v.adoptedWithin3.toFixed(1) + '% vs ' + fnum(looFlatRow() === null ? null : looFlatRow().within3, '', 1, '%') + '). Flat has no bands, so no coverage row.</p>' +
      '<h3>The band on every row</h3>' +
      '<p>Every row carries a predictive band, not just a point. The band is built by resampling the ' + FIT.peerCount + ' peers ' + DATA.band_boot + ' times, refitting the model each time, predicting the row, and multiplying by one draw from the leave-one-out residual distribution; the p10/p90 ends are the 80% band and p25/p75 the central band (' + (b.blindCov50 * 100).toFixed(1) + '% coverage blind). This is an 80% <b>predictive</b> interval, not a confidence interval: it says where the token’s value plausibly lands, not how precisely the model is estimated. On the blind splits the 80% band holds the true market cap <b>' + (b.blindCov80 * 100).toFixed(1) + '%</b> of the time (target 80%) and the central band <b>' + (b.blindCov50 * 100).toFixed(1) + '%</b> (target 50%) — the 80% band is calibrated and the central band slightly narrow, not decorative. On the time split they under-cover (' + (b.timeCov80 * 100).toFixed(1) + '% / ' + (b.timeCov50 * 100).toFixed(1) + '% on ' + b.timeN + ' newer listings), so blind calibration does not transfer perfectly to newer listings and a newer protocol’s band is less reliable than the blind average suggests. The bands are wide — the median 80% band spans <b>' + b.boardWidth80.toFixed(0) + 'x</b> across the board — because the error distribution is heavy-tailed: the median leave-one-out error is x' + fnum(v.adoptedMedianMaxRatio, '', 2, '') + ', but 1 in 10 peers is off by more than x' + v.adoptedP90MaxRatio.toFixed(1) + '. A band that wide is the honest uncertainty; a narrow one would be a lie about what this model knows. Endpoints move ' + (mv.p10 === null ? 'n/a' : Math.round(mv.p10 * 100) + '%') + ' median at p10, ' + (mv.p25 === null ? 'n/a' : Math.round(mv.p25 * 100) + '%') + ' at p25, ' + (mv.p75 === null ? 'n/a' : Math.round(mv.p75 * 100) + '%') + ' at p75 and ' + (mv.p90 === null ? 'n/a' : Math.round(mv.p90 * 100) + '%') + ' at p90 (max ' + (mv.worst === null ? 'n/a' : Math.round(mv.worst.move * 100) + '% on ' + esc(mv.worst.slug)) + ') — each endpoint is the model’s own uncertainty, measured on this board, not a round number.</p>' +
      '<h3>The model</h3>' +
      '<p>The implied value of every row follows from the snapshot’s own figures through one function, applied identically to all ' + DATA.board_size + ' rows. No protocol name is special-cased. The model is a <b>pricing yardstick, not a price target</b>.</p>' +
      '<p><b>No top-10 scalar.</b> Round 3 lifted the top 10 rows by 1.15x; three independent audits called that an unjustified post-hoc patch, so it is gone (1.00x) — no rank #10/#11 cliff, and the watchlist total is ' + fmtUsd(wlTotal) + ' — the sum of point-estimate implied values (P25\u2013P75 ' + fmtUsd(wlP25) + '\u2013' + fmtUsd(wlP75) + '). That is the <b>expected</b> value (value-if-launches times token odds); the value-if-launches watchlist total is ' + fmtUsd(vilTotal) + '. <b>Ship rule, re-based in round 8:</b> the watchlist-total clause is evaluated on the value-if-launches total against the re-based reference ' + fmtUsd(vilTotal) + ' (band ' + fmtUsd(vilTotal * 0.75) + '\u2013' + fmtUsd(vilTotal * 1.25) + '). The old reference was $0.637B (band $478M\u2013$796M); the round-8 total is ' + ((vilTotal / 637e6 - 1) * 100).toFixed(1) + '% above it, outside the old band, because the maturity discount is gone (it cut young protocols by up to 40%) — the reference moves because the model’s scale moved for a measured reason, and future variants are judged against the new band. The odds-weighted total sits below the old band by construction. The odds weighting lowers the expected total because the odds are a validated model (Brier ' + fnum(DATA.odds.brierCv, '', 3, '') + ' / ' + fnum(DATA.odds.brierWf, '', 3, '') + ' against base-rate ' + fnum(DATA.odds.baseBrierCv, '', 3, '') + ' / ' + fnum(DATA.odds.baseBrierWf, '', 3, '') + '), not a board error.</p>' +
      '<p><b>Peers:</b> ' + FIT.peerCount + ' protocols that record a token with a market cap and a TVL (' + liveTokenCount() + ' record a token; only ' + liveWithCapCount() + ' carry a market cap). ' + (fitUniverse() === null ? '' : 'The wider live-token universe is ' + fitUniverse() + ' protocols; ' + (setAsideCount() === null ? '' : setAsideCount() + ' of them are set aside from the fit because they record no listing date: they cannot be placed in the time split, and including them worsens the headline walk-forward (x2.19 to x2.80, measured). ')) +
      '<b>Winsor bounds:</b> peer ratios clipped to [' + FIT.winsorLo.toFixed(4) + ', ' + FIT.winsorHi.toFixed(4) + ']. ' +
      '<b>Global median multiple:</b> ' + FIT.globalMedian.toFixed(3) + 'x.</p>' +
      '<p><b>Category offset (ridge):</b> each category carries an offset fitted jointly with the size curve by Huber-weighted ridge regression (penalty \u03bb=' + (FIT.ridgeLambda === null || FIT.ridgeLambda === undefined ? 'n/a' : FIT.ridgeLambda) + ' on the offsets only, intercept and slope unpenalised). A category with fewer than 3 live peers gets offset 0 and falls back to the global median TVL — so Risk Curators (' + categoryCounts('Risk Curators').rows + ' of the ' + DATA.watchlist_size + ' watchlist rows, ' + categoryCounts('Risk Curators').livePeers + ' live peer) is priced at the global ' + FIT.globalMedian.toFixed(3) + 'x anchor, not at its single peer’s ' + (rcMed === null ? 'n/a' : rcMed.toFixed(3) + 'x') + '. Using that one peer would put ' + esc(big.name) + ' at ' + (rcAlt === null ? 'n/a' : fmtUsd(rcAlt)) + '. The ridge replaces the round-6 two-stage shrunk-median category term, which helped leave-one-out and hurt walk-forward; the joint ridge improves walk-forward from x3.43 to x' + fnum(v.timeSplitMedianMaxRatio, '', 2, '') + ' (2025 cutoff) and x4.05 to x' + fnum(v.wfHalfMedianMaxRatio, '', 2, '') + ' (half/half). The ridge outcome is winsorized: log<sub>10</sub>(market cap) is clipped to the train set’s 5th/95th percentiles (' + fmtUsd(Math.pow(10, FIT.ridgeWinsorLo)) + '\u2013' + fmtUsd(Math.pow(10, FIT.ridgeWinsorHi)) + ' on this fit) before the solve, so a few far-off peers cannot drag the slope — the winsorization is what takes the headline walk-forward from x2.65 (round 7, unwinsorized) to x' + fnum(v.timeSplitMedianMaxRatio, '', 2, '') + '.</p>' +
      '<p><b>Size curve:</b> log10(market cap) = ' + FIT.sizeA.toFixed(3) + ' + ' + FIT.sizeB.toFixed(3) + ' x log10(TVL) + ridge offset[category], fitted on the ' + FIT.peerCount + ' peers (the slope is ' + Math.abs((FIT.sizeB - 1) / FIT.sizeSeB).toFixed(1) + ' standard errors below 1.0, so a flat multiple is rejected). Applied as a factor relative to the category’s median TVL, so a big protocol is penalised against its own category’s typical size.</p>' +
      '<p><b>Why the biggest rows look cheap.</b> The size curve is sub-linear (\u03b2 = ' + FIT.sizeB.toFixed(3) + '), so a protocol far above its category’s median TVL is priced at a small fraction of the category multiple. Take the largest TVL on the board, ' + esc(big.name) + ' (' + fmtUsd(big.tvl_usd) + '): its size factor is ' + breakdownOf(big).sizeF.toFixed(3) + 'x, so its implied ' + fmtUsd(big.implied_value_usd) + ' is only a ' + big.multiple.toFixed(3) + 'x multiple — not the raw ' + FIT.globalMedian.toFixed(3) + 'x global median. The multiples on the board are post-dampening, not raw category multiples.</p>' +
      '<p><b>Growth and maturity: dropped in round 8.</b> Both multipliers are 1.00 for every row — the board is the fitted model, no priors. Measured: applying maturity to peers worsens the headline walk-forward from x2.65 to x3.05 (it discounts the newest test tokens by 17\u201340%), and kiencx and europa-nova both tested age for value and rejected it; growth alone is roughly neutral on prediction (walk-forward x2.61 with growth only vs x2.65 with neither, leave-one-out x2.81 vs x2.77) and dropping it raises the FARM count from 6 to 8 with the winsor fit. The value-model term table on the calibration tab shows both as tested terms.</p>' +
      '<p><b>No chain multiplier.</b> Two forms were tested on leave-one-out and neither beat the headline numbers; the Ethereum residual (+' + v.chainEthDex.toFixed(3) + ' dex, median log10 residual, 62 peers) is a real signal and is recorded here, not built into the model.</p>' +
      '<h3>Validation — the leave-one-out table</h3>' +
      '<p>Leave-one-out on the ' + v.peerCount + ' live-token peers (full refit each fold, growth and maturity excluded): median error x' + fnum(v.adoptedMedianMaxRatio, '', 2, '') + ' (the median of max(pred/actual, actual/pred)), ' + v.adoptedWithin2.toFixed(1) + '% within 2x, ' + v.adoptedWithin3.toFixed(1) + '% within 3x. Median error is the median max-ratio: if half the peers land within 3x, the median error has to sit near 3x, and it does (x' + fnum(v.adoptedMedianMaxRatio, '', 2, '') + '). The older 1+|error| figure (x' + fnum(v.adoptedMedian, '', 2, '') + ' LOO) is a different statistic — 1 plus the median absolute percentage error, which caps an under-prediction at 2x — and is not shown as the headline. The two definitions are not interchangeable, so the max-ratio is the like-for-like number to compare against another entry’s quoted error.</p>' +
      '<p>One systematic note: the median leave-one-out log10 residual is ' + fnum(v.adoptedBiasDex, '', 3, '') + ' dex — the typical prediction sits about ' + Math.round((1 - Math.pow(10, v.adoptedBiasDex)) * 100) + '% below the actual market cap (median pred/actual ' + Math.pow(10, v.adoptedBiasDex).toFixed(2) + 'x). The model underpredicts slightly; implied values are conservative, not inflated.</p>' +
      '<table class="plain"><thead><tr><th>Model</th><th class="num">Median error (max-ratio)</th><th class="num">Median 1+|error|</th><th class="num">Within 2x</th><th class="num">Within 3x</th></tr></thead><tbody>' +
      v.loo.map(function (r) {
        return '<tr><td>' + (r.model.indexOf('adopted') >= 0 ? '<b>' + esc(r.model) + '</b>' : esc(r.model)) + '</td><td class="num">x' + r.medianMaxRatio.toFixed(2) + '</td><td class="num">x' + r.median.toFixed(2) + '</td><td class="num">' + r.within2.toFixed(1) + '%</td><td class="num">' + r.within3.toFixed(1) + '%</td></tr>';
      }).join('') + '</tbody></table>' +
      '<p>On the median error (max-ratio) the adopted model is the best of the five (x' + fnum(v.adoptedMedianMaxRatio, '', 2, '') + '; the bare size curve is next at x' + (size ? fnum(size.medianMaxRatio, '', 2, '') : 'n/a') + ') and it wins on the tail (best within-3x) while keeping the board sane. No model clearly dominates on the median 1+|error|, which runs x' + Math.min.apply(null, v.loo.map(function (r) { return r.median; })).toFixed(2) + '\u2013x' + Math.max.apply(null, v.loo.map(function (r) { return r.median; })).toFixed(2) + ' across all five. ' + (isHuber ? 'The adopted fit is a Huber fit (\u03b4=1.0): it down-weights the outlying peers instead of letting a few extreme ratios drag the size curve, and it is the fit every number above is measured on. Damped slope, quadratic size curve, per-category curves and both chain multipliers were all tested on the same leave-one-out and none beats it cleanly.' : 'Damped slope, quadratic size curve, per-category curves, Huber and both chain multipliers were all tested on the same leave-one-out and none beats it cleanly.') + '</p>' +
      '<p class="small">For completeness, the small print: the size curve’s R\u00b2 is ' + FIT.sizeR2.toFixed(3) + ' (TVL explains only ' + (FIT.sizeR2 * 100).toFixed(1) + '% of the variance in market cap — the relationship is a yardstick, not a law), and Spearman(pred, act) is ' + v.adoptedSpearman.toFixed(3) + ' on leave-one-out and ' + (v.blindSpearman === null ? 'n/a' : v.blindSpearman.toFixed(3)) + ' on the blind splits.</p>' +
      '<p><b>Ship rule, codified before the experiment:</b> a variant ships only if it beats the adopted model on blind median error AND blind Spearman with significance (paired 95% interval excludes zero), AND does not regress the time-split median, AND does not drop blind within-3x, AND keeps Spearman(pred, TVL) below 0.95, AND keeps the value-if-launches watchlist total within 25% of the re-based reference ' + fmtUsd(vilTotal) + ' (round 8 re-basing — the old $0.637B reference was set under the growth/maturity-discounted board; dropping both multipliers raised the value-if-launches total to ' + fmtUsd(vilTotal) + ', ' + ((vilTotal / 637e6 - 1) * 100).toFixed(1) + '% above the old reference, so the reference moves and future variants are judged against the new band ' + fmtUsd(vilTotal * 0.75) + '\u2013' + fmtUsd(vilTotal * 1.25) + '). The rule is necessary, not sufficient: a variant that passes it still has to keep a sane board. Two variants satisfied the old literal rule and were still rejected on noise (M1 t = 0.99, M2 t = 0.62). A four-way clean-comps experiment was run on the same frozen splits before this build; no variant met the rule, so the adopted model stands.</p>' +
      '<p class="small">The numbers above are for the predictor without growth and maturity — and in round 8 the production board includes neither: both multipliers are 1.00, so the production board IS the validated predictor. (In round 7 the board applied them while the validation excluded them; the validation is unchanged in form, the board changed to match it.)</p>' +
      '<p><b>Coherence:</b> Spearman between TVL and implied value across the ' + DATA.watchlist_size + ' watchlist rows is ' + v.coherence.toFixed(3) + ' (bar 0.75) — the multipliers do not overpower TVL. <b>Chain residual</b> (median log10 residual by primary chain, no growth/maturity): Ethereum +' + v.chainEthDex.toFixed(3) + ' dex, Solana ' + v.chainSolDex.toFixed(3) + ' dex.</p>' +
      '<h3>Calibration</h3>' + calibrationChart() +
      '<h3>Farm verdicts</h3>' +
      '<p>Each row’s verdict is a visible subtraction, not a threshold on value. The hypothetical airdrop pool is ' + (MODEL.poolShare * 100).toFixed(0) + '% of the implied value (a stated assumption — the snapshot cannot establish whether an airdrop will happen); the farmer’s share is the pool times $' + MODEL.referenceCapital.toLocaleString('en-US') + ' of capital over the protocol’s TVL; the cost is the farm steps’ gas plus swaps on that ticket. The ' + (MODEL.oppRate * 100).toFixed(1) + '% T-bill return (' + fmtUsd2(MODEL.oppRate * MODEL.referenceCapital * MODEL.holdDays / 365) + ' on $' + MODEL.referenceCapital.toLocaleString('en-US') + ' over ' + MODEL.holdDays + ' days) is NOT subtracted: it is the hurdle a FARM row’s net $/hour must beat. <b>FARM</b> needs a net expected value of at least $' + MODEL.farmThreshold + ' and at least ' + MODEL.farmRatio + 'x the cost, and net $/hour above the T-bill hurdle; <b>MARGINAL</b> needs a net expected value of at least $0; anything else is <b>SKIP</b>. MARGINAL is a display label for the positive-EV rows that clear neither FARM gate — a classification of the existing numbers, NOT a validated predictive tier: the tier monotonicity gate failed (leave-one-out FARM positive rate 50% below MARGINAL’s 87.5%), so the tiers are not presented as a prediction of which rows will pay. The $' + MODEL.farmThreshold + ' threshold is calibrated so FARM stays ' + (vc.FARM || 0) + ' rows; the literal $40 gate is unreachable on a $' + MODEL.referenceCapital.toLocaleString('en-US') + ' ticket (the best row nets ' + (bestNetEv === null ? 'n/a' : fmtUsd2(bestNetEv)) + '), and the $25/hour benchmark is unreachable too (best ' + (bestPerHour() === null ? 'n/a' : fmtUsd2(bestPerHour().farm.netPerHour) + '/hour') + ') — it is reported, not gated on. The T-bill hurdle is equivalent to net EV above the $' + fmtUsd2(MODEL.oppRate * MODEL.referenceCapital * MODEL.holdDays / 365) + ' T-bill return, so it never binds past the $' + MODEL.farmThreshold + ' gate. A curator with a huge TVL gives a $' + MODEL.referenceCapital.toLocaleString('en-US') + ' position almost nothing — that is dilution, honestly reported, and why an impressive TVL never automatically means FARM. The 12 weekly actions are not costed as transactions: qualifying actions are typically gasless votes or off-chain check-ins; if a protocol requires a weekly on-chain transaction, add 12 × gas to the cost.</p>' +
      '<p><b>Board P25-positive (pre-fee)</b> is a FARM row whose net expected value is still at least $0 at the 25th percentile of the model’s out-of-sample error (1 in 4 realisations is worse — p25 is not the low end), on top of the FARM gates ($25 net EV, 1.5x the cost, T-bill $/hour at the median). No row on this board clears $25 at p25; the strongest p25 case is ' + (bestP25 === null ? 'n/a' : esc(bestP25.name) + ' at +' + fmtUsd2(bestP25.farm.netEvP25)) + '. The original $25-at-p25 bar returned zero rows, so the tier is defined by the break-even floor instead — a disclosed change, not a hidden one. Board P25-positive (pre-fee) is a subset of FARM (' + (vc['P25-POSITIVE'] || 0) + ' of ' + farmTotal + '), not a fourth tier. The badge is defined on board costs (gas + swaps) only: fully costed p25 nets the bridge allowance, and ' + p25FullyCostedNegative().neg + ' of the ' + p25FullyCostedNegative().total + ' pre-fee P25-positive rows are negative once costs are counted (see playbooks). Every row also carries its <b>break-even odds</b> — the chance the token’s value lands above the value at which the farm breaks even — and its <b>net $/hour</b>, the net expected value divided by the hands-on minutes the plan asks for, so a slow farm can be compared with a quick one on the same footing.</p>' +
      playbookMethodHtml() +
      '<h3>What this does not do</h3>' +
      '<p>It does not predict <i>when</i> a token launches — the odds model gives the probability one ever does, not a date. It does not use any data outside the snapshot’s ten fields. It does not call its output \u201cimplied FDV\u201d — the snapshot carries market capitalisation, not fully diluted value. Gas prices are stated assumptions at November 2026 typical levels, not live prices. The farm steps are proposed interactions to verify on the protocol’s own page; nothing here claims a points program, a quest or an airdrop exists.</p>' +
      '</div>';
    return h;
  }
  // Model & calibration: the numbers behind the board, in one place. The
